import pathlib,subprocess,json,time,hashlib
R=pathlib.Path.cwd();S=R/'evaluations/T-0812/implementation/stage478-v1';db=S/'stage.sqlite';start=time.monotonic();checks=[]
for name,args in [('P-0254-person.json',['person','P-0254','--full','--format','json']),('P-0255-person.json',['person','P-0255','--full','--format','json']),('P-0269-pedigree.json',['pedigree','P-0269']),('P-0270-pedigree.json',['pedigree','P-0270']),('inventory-full.json',['inventory','--full']),('verify.json',['verify']),('verify-assets.json',['verify-assets'])]:
 p=S/name;assert not p.exists();t=time.monotonic();r=subprocess.run(['node','genealogy2/cli.mjs',*args,'--db',str(db)],capture_output=True,text=True);p.write_text(r.stdout);meta={'args':args,'exit':r.returncode,'stderr':r.stderr,'elapsed_seconds':time.monotonic()-t};p.with_suffix('.process.json').write_text(json.dumps(meta,indent=2)+'\n');assert r.returncode==0,r.stderr;json.loads(r.stdout);checks.append({'path':str(p.relative_to(R)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),**meta})
(S/'reader-capture-result.json').write_text(json.dumps({'checks':checks,'elapsed_seconds':time.monotonic()-start,'stage_db_sha256':hashlib.sha256(db.read_bytes()).hexdigest()},indent=2)+'\n');print('reader captures PASS')
